"""The Power BI report (2026-10-13): powerbi/CareerOS.pbip, generated by tools/build_powerbi_project.py.

Power BI Desktop is not available to the tests, so they prove what can be proved without it:
- the committed project is exactly what the generator builds (nothing was edited by hand or saved over by Desktop);
- every relationship follows the analytics export's references, with one active path per fact and dimension;
- every field a visual uses, and every column or measure a measure names, exists, and every RELATED has a
  relationship to follow (a missing one broke two visuals the first time the report was opened);
- the measures are exactly those of docs/powerbi_dashboard_spec.md;
- the report loads the synthetic demo sample, never a private vault.
The report itself was opened, refreshed and checked page by page in Power BI Desktop 2.158 (spec, section 6).
"""
import json
import re
import shutil
import sys
import tempfile
import unittest
from pathlib import Path

from careeros.analytics.export import REFERENCES, TABLES
from careeros.paths import ENGINE_ROOT

sys.path.insert(0, str(ENGINE_ROOT / "tools"))
import build_powerbi_project as pbi  # noqa: E402

PROJECT = ENGINE_ROOT / "powerbi"
SPEC = ENGINE_ROOT / "docs" / "powerbi_dashboard_spec.md"
GENERATED_ONLY = ("CareerOS.pbip", "CareerOS.SemanticModel", "CareerOS.Report")


def files(root: Path) -> dict:
    out = {}
    for part in GENERATED_ONLY:
        base = root / part
        for f in ([base] if base.is_file() else sorted(base.rglob("*"))):
            if f.is_file() and ".pbi" not in f.relative_to(root).parts:
                out[str(f.relative_to(root))] = f.read_bytes()
    return out


class PowerBIProjectTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.model = json.loads((PROJECT / "CareerOS.SemanticModel" / "model.bim").read_text(encoding="utf-8"))["model"]
        cls.folder = re.match(r'"(.*)" meta', next(e for e in cls.model["expressions"] if e["name"] == "ExportFolder")["expression"]).group(1)
        cls.visuals = [json.loads(v.read_text(encoding="utf-8")) for v in (PROJECT / "CareerOS.Report").rglob("visual.json")]

    def test_the_committed_project_is_exactly_what_the_generator_builds(self):
        tmp = Path(tempfile.mkdtemp(prefix="careeros-pbip-"))
        self.addCleanup(shutil.rmtree, tmp, True)
        theme = PROJECT / "CareerOS.Report" / "StaticResources" / "SharedResources" / "BaseThemes" / f"{pbi.THEME}.json"
        pbi.build(tmp, self.folder.replace('""', '"'), theme)
        built, committed = files(tmp), files(PROJECT)
        self.assertEqual(sorted(built), sorted(committed))
        for name in built:
            self.assertEqual(built[name], committed[name], f"powerbi/{name} differs: run tools/build_powerbi_project.py")

    def test_relationships_follow_the_exports_references(self):
        rels = {(r["fromTable"], r["fromColumn"]): r for r in self.model["relationships"]}
        expected = {k: v for k, v in REFERENCES.items() if not k[0].startswith("dim_")}
        self.assertEqual(set(rels), set(expected))
        for key, dim in expected.items():
            self.assertEqual((rels[key]["toTable"], rels[key]["toColumn"]), (dim, TABLES[dim][0][0]), key)
            self.assertEqual(rels[key].get("isActive", True), key not in pbi.INACTIVE, key)
        active = [(r["fromTable"], r["toTable"]) for r in self.model["relationships"] if r.get("isActive", True)]
        self.assertEqual(len(active), len(set(active)), "two active paths between a fact and a dimension")
        self.assertIn(("fact_job_evaluation", "job_key"), rels)   # the job-level fact's own key is its link to dim_job

    def test_every_reference_resolves(self):
        columns = {(t["name"], c["name"]) for t in self.model["tables"] for c in t["columns"]}
        measures = {m["name"]: m for t in self.model["tables"] for m in t.get("measures", [])}
        related_targets = {r["toTable"] for r in self.model["relationships"]}
        problems = []
        for t in self.model["tables"]:
            for c in t["columns"]:
                if "sortByColumn" in c and (t["name"], c["sortByColumn"]) not in columns:
                    problems.append(f"sort {t['name']}.{c['name']}")
        for name, m in measures.items():
            dax = "\n".join(m["expression"]) if isinstance(m["expression"], list) else m["expression"]
            problems += [f"{name}: {t}[{c}]" for t, c in re.findall(r"\b(\w+)\[([^\]]+)\]", dax) if (t, c) not in columns]
            problems += [f"{name}: [{r}]" for r in re.findall(r"(?<![\w\]])\[([^\]]+)\]", dax) if r not in measures]
            problems += [f"{name}: RELATED({t}) has no relationship" for t in re.findall(r"RELATED\s*\(\s*(\w+)\[", dax)
                         if t not in related_targets]
        for v in self.visuals:
            self.assertRegex(v["name"], r"^[\w-]+$")
            for state in v["visual"].get("query", {}).get("queryState", {}).values():
                for p in state["projections"]:
                    f = p["field"]
                    if "Measure" in f:
                        problems += [f"{v['name']}: [{f['Measure']['Property']}]"] if f["Measure"]["Property"] not in measures else []
                    else:
                        key = (f["Column"]["Expression"]["SourceRef"]["Entity"], f["Column"]["Property"])
                        problems += [f"{v['name']}: {key}"] if key not in columns else []
        self.assertEqual(problems, [])

    def test_titles_are_readable(self):
        """S15 (2026-10-31): every column a visual shows has a display name, so no subtitle or axis shows a raw field
        name, and every KPI card is wide enough for its title (8 px a character at the 12 pt default label, 7 at 10 pt,
        plus 40 px of padding; eight cards across cut most titles off)."""
        problems = []
        for v in self.visuals:
            for state in v["visual"]["query"]["queryState"].values():
                problems += [f"{v['name']}: {p['queryRef']} has no display name" for p in state["projections"]
                             if "Column" in p["field"] and not p.get("displayName")]
            if v["visual"]["visualType"] == "card":
                labels = v["visual"].get("objects", {}).get("categoryLabels", [{}])[0].get("properties", {})
                size = float(labels["fontSize"]["expr"]["Literal"]["Value"].rstrip("D")) if "fontSize" in labels else 12
                title = v["visual"]["query"]["queryState"]["Values"]["projections"][0]["nativeQueryRef"]
                needed = 40 + len(title) * (8 if size >= 12 else 7)
                if v["position"]["width"] < needed:
                    problems.append(f"{v['name']}: '{title}' needs {needed} px, has {v['position']['width']}")
        self.assertEqual(problems, [])

    def test_the_measures_are_those_of_the_dashboard_spec(self):
        documented, in_dax = set(), False
        for line in SPEC.read_text(encoding="utf-8").splitlines():
            if line.startswith("```"):
                in_dax = line.strip() == "```dax"
                continue
            match = re.match(r"^(?!VAR )([A-Z][\w /()-]*?) =", line) if in_dax else None   # a definition, not a DAX variable
            if match:
                documented.add(match.group(1).strip())
        self.assertEqual(documented, {name for name, _, _ in pbi.MEASURES})

    def test_applications_keeps_the_status_filter_of_its_chart(self):
        """Codex CR-2026-11-01-OBS-REVIEW, F4: a Boolean filter in CALCULATE replaces any filter on the same column, so
        "Applications by status" (fact_application[current_state] on its axis) and a status slicer would get every
        non-void application on each status. The void exclusion is inside KEEPFILTERS, which narrows that filter
        instead. (DAX is not run here: Power BI Desktop is not available to the tests.)"""
        expected = 'CALCULATE ( COUNTROWS ( fact_application ), KEEPFILTERS ( fact_application[current_state] <> "void" ) )'
        built = {name: expr for name, expr, _ in pbi.MEASURES}
        committed = {m["name"]: m["expression"] for t in self.model["tables"] for m in t.get("measures", [])}
        self.assertEqual((built["Applications"], committed["Applications"]), (expected, expected))
        self.assertIn(f"Applications = {expected}", SPEC.read_text(encoding="utf-8"))
        chart = next(v["visual"]["query"]["queryState"] for v in self.visuals if v["name"] == "pipe_apps")
        self.assertEqual([p["field"]["Column"]["Property"] for p in chart["Category"]["projections"]], ["current_state"])
        self.assertEqual([p["field"]["Measure"]["Property"] for p in chart["Y"]["projections"]], ["Applications"])
        status_filters = re.findall(r"(KEEPFILTERS \( )?fact_application\[current_state\]", built["Applications"])
        self.assertEqual(status_filters, ["KEEPFILTERS ( "])   # no filter on the chart's own column outside KEEPFILTERS

    def test_every_page_and_table_of_the_spec_is_built(self):
        self.assertEqual([p[1] for p in pbi.PAGES], ["Executive overview", "Employer intelligence", "Job pipeline", "Role intelligence",
                                                     "System quality"])
        self.assertEqual({t["name"] for t in self.model["tables"]}, set(TABLES) | {"_Measures"})
        date = next(t for t in self.model["tables"] if t["name"] == "dim_date")
        self.assertEqual(date.get("dataCategory"), "Time")
        self.assertTrue(next(c for c in date["columns"] if c["name"] == "date").get("isKey"))

    def test_the_report_loads_the_synthetic_demo_sample(self):
        self.assertTrue(self.folder.replace("/", "\\").lower().endswith("samples\\analytics_demo"), self.folder)
        self.assertNotIn("vault", self.folder.lower())


if __name__ == "__main__":
    unittest.main()
